import{d as p,C as n,o as d,c as g,a3 as s,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十章","description":"《正易心法》第十章——粤乾与坤，即是阴阳：乾坤纯而不驳、圆融合粹，引《老子》「天得一以清，地得一以宁」印证；尽乾之道为圣，尽坤之道为贤。","frontmatter":{"title":"正易心法·第十章","description":"《正易心法》第十章——粤乾与坤，即是阴阳：乾坤纯而不驳、圆融合粹，引《老子》「天得一以清，地得一以宁」印证；尽乾之道为圣，尽坤之道为贤。","category":"guide","aliases":["正易心法第十章","粤乾与坤即是阴阳","纯而不驳"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-10.md","filePath":"yijing/zheng-yi-xin-fa/chapter-10.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-10.md"},x=p({...c,setup(u){const o=[{id:"z10-01",label:"一、乾坤即是阴阳",showLabel:!0,sentences:[["粤乾与坤，即是阴阳。",{text:"圆融",glossary:"yuanrong"},"合粹，平和之中。"]],note:["「粤」是句首发语词。乾与坤，就是阴阳本身——圆满融通、纯粹合一，处于平和之中。（注意「即是」二字：乾坤不是阴阳的「象征」，而是阴阳本身的卦画写照。这一点与《系辞传》「乾，阳物也；坤，阴物也」的说法有细微不同——后者说乾坤是阴阳的「物」，麻衣直接说乾坤「就是」阴阳。）"]},{id:"z10-02",label:"二、纯而不驳",showLabel:!0,sentences:[["凡阴阳之气，纯而不驳，是为乾坤。"]],note:["凡是阴阳之气，纯粹而不驳杂，就是乾坤。（「驳」是杂乱不纯。与第九章合读更清楚：乾坤各守其纯，是本体；一旦异类爻混入，纯被打破，即成六子——**纯（乾坤）→ 破体 → 驳（六子）→ 万物化生**，这是从本体到现象的生成过程。）"]},{id:"z10-03",label:"三、老子得一",showLabel:!0,sentences:[["《老子》曰：“天",{text:"得一",glossary:"deyi"},"以清，地得一以宁。”正谓此也。"]],note:["《老子》说：「天得一而清明，地得一而安宁。」说的正是这个道理。（《老子》三十九章原文后面还有「神得一以灵，谷得一以盈，万物得一以生，侯王得一以为天下正」。这里的「一」不是数字 1，而是**纯粹、完整、不驳杂的本性**——天得一就是乾守纯阳，地得一就是坤守纯阴。这是本书唯一一次引用道家经典，也正是陈抟一脉「以道解易」的思想标记。）"]},{id:"z10-04",label:"四、圣贤各尽乾坤",showLabel:!0,sentences:[["因知能尽乾之道，是为圣人；能尽坤之道，是为贤人。"]],note:["由此可知：能完全体现乾之道的，是圣人；能完全体现坤之道的，是贤人。（这里没有「圣人高于贤人」的意思——**圣人尽乾（纯阳之德：刚健、创造、光明），贤人尽坤（纯阴之德：柔顺、承载、厚德），是两种完整的、并列的人格**。这里的「尽」是关键：不是「靠近」，而是「完全体现而不驳杂」；驳杂（既非纯阳也非纯阴）才是普通人的状态。）"]}],i=[{id:"yuanrong",term:"圆融",pinyin:"yuán róng",meaning:"圆满融通，无所滞碍。阴阳之气运行无碍。"},{id:"deyi",term:"得一",pinyin:"dé yī",meaning:"《老子》三十九章语。此处「一」不是数字，而是纯粹、完整、不驳杂的本性：天得一即乾守纯阳，地得一即坤守纯阴。"}];return(b,t)=>{const r=n("DaoTextReading"),l=n("DaoKeywordCards");return d(),g("div",null,[t[0]||(t[0]=s(`<h1 id="正易心法·第十章" tabindex="-1">正易心法·第十章 <a class="header-anchor" href="#正易心法·第十章" aria-label="Permalink to &quot;正易心法·第十章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章极短，却有三个层次：</p><p><strong>第一层（本体论）：乾坤即是阴阳，纯而不驳</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是说乾「代表」阳、坤「代表」阴</span></span>
<span class="line"><span>而是说乾坤就是阴阳本身的卦画形式</span></span>
<span class="line"><span>两者直接等同，无需中介</span></span></code></pre></div><p><strong>第二层（引证）：以《老子》「得一」印证</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「一」= 纯粹不驳的本性</span></span>
<span class="line"><span>天得一 = 乾守纯阳 → 天清明不浊</span></span>
<span class="line"><span>地得一 = 坤守纯阴 → 地安宁不动</span></span></code></pre></div><p><strong>道家与易学在这里汇合</strong>：道家的「一」＝易学的「纯阳／纯阴」。</p><p><strong>第三层（人格论）：圣人尽乾，贤人尽坤</strong></p><p>从天地（乾坤）落到人（圣贤）——<strong>天人同构的最后一步</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天之纯阳 = 乾 = 圣人之德（刚健、创造、光明）</span></span>
<span class="line"><span>地之纯阴 = 坤 = 贤人之德（柔顺、承载、厚德）</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>为什么引《老子》而不引《系辞》？</strong></p><p>《系辞传》本可引用：「乾，阳物也；坤，阴物也」「乾道成男，坤道成女」——但麻衣选择了《老子》：</p><table tabindex="0"><thead><tr><th></th><th>表述</th><th>侧重</th></tr></thead><tbody><tr><td>《系辞传》</td><td>乾坤是阴阳的「<strong>物</strong>」（象征物）</td><td>象征论</td></tr><tr><td>《老子》</td><td>天地得「<strong>一</strong>」而清宁（本性论）</td><td>本性论</td></tr></tbody></table><p><strong>麻衣要强调的是：乾坤不是阴阳的象征，而是阴阳「得一」（纯粹）的状态——这个意思《老子》表达得更准确。</strong> 这也暗示了麻衣的思想背景：<strong>易学与道家在「纯粹本性」这一点上是同一件事。</strong></p><p><strong>「圣人尽乾，贤人尽坤」的深意</strong>：</p><p>为什么不是「圣人同时尽乾坤」？——因为<strong>乾坤各有其「纯」，纯 = 不驳杂 = 完全体现一种本性</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>圣人尽乾：完全体现刚健创造之德（如孔子「学而不厌，诲人不倦」）</span></span>
<span class="line"><span>贤人尽坤：完全体现柔顺承载之德（如颜回「不迁怒，不贰过」）</span></span></code></pre></div><p><strong>关键不在圣贤高下，而在于「纯」</strong>——能完全体现乾道而不驳杂，就是圣；能完全体现坤道而不驳杂，就是贤。</p><p><strong>与第九章的张力</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>第九章</td><td><strong>向下</strong>（生成）</td><td>乾坤破体，生六子 → 万物</td></tr><tr><td>第十章</td><td><strong>向上</strong>（回归）</td><td>乾坤纯粹，圆融合粹 → 本源</td></tr></tbody></table><p><strong>两章构成一个完整的宇宙论循环：本体 → 流出 → 回归 → 本体。</strong> 这与道家「道生一，一生二，二生三，三生万物」——「归根曰静，是谓复命」完全吻合。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>注意「<strong>即是</strong>」二字的分量——乾坤不是比喻；</li><li>把《老子》三十九章读一遍（「昔之得一者：天得一以清……」）；</li><li>再读第九、十、十一章三章，看这个**「纯 → 破 → 炼 → 纯」**的循环。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>即是阴阳</strong>：乾坤与阴阳直接等同，非象征。</li><li><strong>纯而不驳</strong>：未被破体之前的纯粹状态。</li><li><strong>得一</strong>：语出《老子》三十九章，即各守其纯。</li><li><strong>圣贤并立</strong>：尽乾之道为圣，尽坤之道为贤。</li><li><strong>回望本源</strong>：展开六子之前，先回看乾坤的纯粹。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,28)),e(r,{colophon:"即是阴阳 · 纯而不驳 · 天得一以清 · 圣贤各尽",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十章原文",sections:o,glossary:i}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（如句首「粤」为发语词），不作统一。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"即是阴阳",pinyin:["jí","shì"],meaning:"「即是」二字是关键：乾坤不是阴阳的象征，而是阴阳本身的卦画写照。"},{term:"纯而不驳",pinyin:["chún","ér"],meaning:"纯粹而不驳杂。乾坤各守其纯，是本体；一旦异类爻混入即成六子。"},{term:"得一",pinyin:["dé","yī"],meaning:"《老子》三十九章：「天得一以清，地得一以宁。」此「一」非数字，而是纯粹完整不驳杂的本性。"},{term:"尽乾之道为圣",pinyin:["jìn","qián"],meaning:"完全体现刚健创造之德即是圣人。与「尽坤之道为贤」并列，非高下之分，关键在「纯」。"},{term:"回望本源",pinyin:["huí","wàng"],meaning:"在展开六子、六十四卦之前，先回看乾坤的纯粹状态——这是一切的起点，也是一切的归宿。"}]}),t[3]||(t[3]=s(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章极短，三个层次一气贯通：<strong>乾坤即是阴阳（本体）→ 纯而不驳、得一（引证）→ 圣贤各尽乾坤（人格）</strong>。</p><p><strong>「即是」二字是关键</strong>：乾坤不是阴阳的象征，而是阴阳本身的卦画形式。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>为什么引《老子》而不引《系辞》？</strong> 这是本书唯一一次引用道家经典，值得注意：</p><table tabindex="0"><thead><tr><th></th><th>表述</th><th>侧重</th></tr></thead><tbody><tr><td>《系辞传》</td><td>乾坤是阴阳的「物」</td><td>象征论</td></tr><tr><td>《老子》</td><td>天地得「一」而清宁</td><td>本性论</td></tr></tbody></table><p>麻衣要说的是<strong>乾坤不是阴阳的象征，而是阴阳「得一」（纯粹）的状态</strong>——这一点《老子》表达得更准确。<strong>这也暗示：易学与道家在「纯粹本性」这一点上是同一件事。</strong></p><p><strong>「圣人尽乾、贤人尽坤」的深意</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>圣人尽乾：完全体现刚健创造之德</span></span>
<span class="line"><span>贤人尽坤：完全体现柔顺承载之德</span></span>
<span class="line"><span>关键不在高下，而在「纯」</span></span>
<span class="line"><span>驳杂（既非纯阳也非纯阴）才是普通人的状态</span></span></code></pre></div><p><strong>与第九章的张力</strong>：第九章是<strong>向下的生成</strong>（乾坤破体→六子→万物），第十章是<strong>向上的回归</strong>（万物→去驳归纯→圣贤→乾坤）。<strong>两章构成完整的宇宙论循环，与道家「归根曰静，是谓复命」完全吻合。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把「即是」二字读慢一点：<strong>乾坤不是比喻</strong>；</li><li>把《老子》三十九章读一遍（「昔之得一者」）；</li><li>记住三章连读的顺序：<strong>九（破）→ 十（纯）→ 十一（炼归纯）</strong>。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>乾与坤，就是阴阳本身——圆满融通、纯粹合一，处于平和之中。</p><p>凡是阴阳之气，纯粹而不驳杂，就是乾坤。</p><p>《老子》说：「天得一而清明，地得一而安宁。」说的正是这个道理。</p><p>由此可知：能完全体现乾之道的，是圣人；能完全体现坤之道的，是贤人。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十章只做了一件事——<strong>把乾坤从「两个卦」还原为「阴阳的纯粹状态本身」，然后接上一句《老子》，让道与易在这里握了手。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「即是」而非「代表」</strong>——一个字的差别，是整章的分量。<strong>我平时说「乾代表阳」时，其实已经把本体降成了象征。</strong></li><li><strong>「引《老子》而非《系辞》」</strong>——这是全书的第一次（也是很重要的一次）道易汇流。<strong>麻衣在说：这两条河的上游是同一个泉。</strong></li><li><strong>「圣人尽乾，贤人尽坤」</strong>——我原先会下意识读成「圣人高于贤人」。<strong>但麻衣的标准是「纯」，不是「高」。</strong> 一个问题浮出来：<strong>我愿意做「纯」的那一个，还是做「大」的那一个？</strong></li><li><strong>「得一」的「一」</strong>——不是数字，是纯粹。<strong>我身上最「驳」的地方在哪里？</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>现实中的人既非纯阳也非纯阴，都是「驳」的状态（六子之象）。那么修养的方向是趋近纯粹，还是在驳杂中找到自己的落处？</strong> 麻衣没有直接回答——但九章（破体）与十章（纯粹）合起来已经暗示了：<strong>先认清自己在六子中的哪一个偏陂（落处），就在那个偏陂里炼；「炼」不是逃离驳杂，而是把驳杂炼回纯粹。</strong> 所以不是二选一，是三步：<strong>找到落处 → 在偏中炼 → 纯体乃成。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 向下的生成（破体）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-11">第十一章 · 至于六子</a> — 向上的回归（炼归纯）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-08">第八章 · 纵横施设</a> — 「对待之理」（乾坤互为错卦）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「乾，阳物也；坤，阴物也」：麻衣的「即是」比「为物」更进一步</li></ul>`,24))])}}});export{y as __pageData,x as default};
